import { useState, useEffect, useCallback, useRef } from 'react';
import debounce from 'lodash/debounce';
import { useDispatch, useSelector } from 'store';

/**
 * Reusable hook for managing table operations (pagination, sorting, selection, search, API fetching).
 */
const useTableManagement = ({ fetchFunction, defaultRowsPerPage = 5, debounceDelay = 500 }) => {
    const dispatch = useDispatch();

    // ✅ Get `page` and `total` from Redux store
    const { pagination } = useSelector((state) => state.inquires);
    const totalRecords = pagination.inquires?.total || 0;
    const reduxPage = pagination.inquires?.page || 0;

    // Table States
    const [rowsPerPage, setRowsPerPage] = useState(defaultRowsPerPage);
    const [page, setPage] = useState(reduxPage); // ✅ Sync with Redux
    const [orderBy, setOrderBy] = useState('id'); // ✅ Default sorting by 'id'
    const [order, setOrder] = useState('asc');
    const [loading, setLoading] = useState(true);
    const [selected, setSelected] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filters, setFilters] = useState({}); // ✅ Stores additional filters (e.g., status, date range)

    const isFirstLoad = useRef(true); // ✅ Prevents double calls on mount

    // ✅ Ensure Redux `page` and local `page` are in sync
    useEffect(() => {
        if (page !== reduxPage) {
            setPage(reduxPage);
        }
    }, [reduxPage]);

    // Fetch Data with Artificial Delay for Smooth UX
    const fetchData = useCallback(
        async (params = {}, callback) => {
            console.log('parem', params, 'filters', filters);
            setLoading(true);
            try {
                await new Promise((resolve) => setTimeout(resolve, 200)); // ✅ Smooth UX

                const mergedParams = {
                    limit: rowsPerPage,
                    page,
                    orderBy,
                    order,
                    searchParams: params // ✅ Explicitly pass filters
                    // ...params // ✅ Merge new parameters (search, sorting, etc.)
                };
                console.log('mergedParams', mergedParams);

                await dispatch(fetchFunction(mergedParams));

                if (callback) callback(); // ✅ Callback after API call
            } finally {
                setLoading(false);
            }
        },
        [dispatch, fetchFunction, rowsPerPage, page, orderBy, order, filters]
    );

    // ✅ Debounced API call for search
    const debouncedSearch = useCallback(
        debounce((query) => {
            setSearchQuery(query.toLowerCase()); // ✅ Updates after delay
            fetchData({ search: query.toLowerCase() });
        }, debounceDelay),
        [debounceDelay]
    );

    // Cleanup debounce function on unmount
    useEffect(() => () => debouncedSearch.cancel(), [debouncedSearch]);

    // ✅ Prevent duplicate API calls on load
    useEffect(() => {
        if (isFirstLoad.current) {
            isFirstLoad.current = false;
            fetchData();
        }
    }, []); // ✅ Runs **only on first load**

    // ✅ Ensures `fetchData` runs **only after state updates**
    const handlePageChange = (event, newPage) => {
        if (newPage !== page) {
            setPage(newPage);
            fetchData({ page: newPage });
        }
    };

    // ✅ Ensures `fetchData` runs **only after state updates**
    const handleRowsPerPageChange = (event) => {
        const newRowsPerPage = parseInt(event.target.value, 10);
        if (newRowsPerPage !== rowsPerPage) {
            setRowsPerPage(newRowsPerPage);
            fetchData({ limit: newRowsPerPage });
        }
    };

    // ✅ Sorting Handler (Handles both `order` and `orderBy`)
    const handleSortChange = (property) => {
        setOrderBy((prevOrderBy) => {
            const isAsc = prevOrderBy === property && order === 'asc';
            const newOrder = isAsc ? 'desc' : 'asc';

            setOrder(newOrder);
            fetchData({ orderBy: property, order: newOrder });

            return property;
        });
    };

    // ✅ Debounced Search Handler (Replaces `useTableFilters`)
    const handleSearch = (query) => {
        if (!query || typeof query !== 'string') return;
        debouncedSearch(query);
    };
    // ✅ Filters Handler (E.g., Status, Date Range, etc.)
    const handleFilters = (newFilters) => {
        console.log('filter here', newFilters);
        if (!newFilters || typeof newFilters !== 'object') return;

        console.log('filter here', newFilters);

        setFilters((prevFilters) => {
            const updatedFilters = { ...prevFilters, ...newFilters };
            console.log('updatedFilters', updatedFilters);
            fetchData(updatedFilters); // ✅ Ensure fetchData gets the updated filters
            return updatedFilters;
        });
    };

    // Selection Handlers
    const handleSelectAll = (event, data) => {
        if (!Array.isArray(data)) {
            console.error('handleSelectAll: data is not an array', data);
            return;
        }

        if (event.target.checked) {
            setSelected(data?.map((item) => item.id)); // ✅ Select all IDs
        } else {
            setSelected([]); // ✅ Deselect all
        }
    };

    const handleRowClick = (event, id) => {
        console.log('here row', id);

        setSelected((prevSelected) => (prevSelected.includes(id) ? prevSelected.filter((item) => item !== id) : [...prevSelected, id]));
    };

    return {
        rowsPerPage,
        page,
        totalRecords, // ✅ Exposed for UI usage
        orderBy,
        order,
        loading,
        selected,
        setSelected,
        fetchData,
        handlePageChange,
        handleRowsPerPageChange,
        handleSortChange, // ✅ Exposed sorting handler
        handleSearch, // ✅ Now search is handled inside this hook
        handleFilters, // ✅ Added filter handling
        handleSelectAll,
        handleRowClick,
        setLoading
    };
};

export default useTableManagement;
